package dev.specialclient;

/** Instruction, not ten automation algorithms. Modern vanilla timing differs from 1.8. */
public final class BridgeLessons {
    public record Lesson(String title, String difficulty, String[] steps) {}
    public static final Lesson[] ALL = {
        new Lesson("Sneak bridge", "Beginner", new String[]{"Use a flat practice platform and disposable blocks.", "Face the starting block, then look down toward its outer edge.", "Hold sneak and move backward slowly; place against the exposed side.", "Pause every block and check your crosshair still hits a block face.", "Goal: build 8 blocks without falling. Speed comes later."}),
        new Lesson("Diagonal sneak", "Beginner", new String[]{"Start at a platform corner with a clear diagonal route.", "Face back toward the platform corner, roughly 45 degrees to its edges.", "Sneak backward with a strafe key; keep the side face in your crosshair.", "Alternate the exposed faces; do not aim into empty air.", "Goal: 6 diagonal steps, then repeat with fewer corrections."}),
        new Lesson("Ninja / speed", "Intermediate", new String[]{"First complete an 8-block sneak bridge.", "Place a block while sneaking at the edge.", "Briefly release sneak over safe block centers, then sneak before the next edge.", "Keep backward movement steady. Shorten the release if you fall.", "Goal: 8 blocks with controlled, repeatable sneak timing."}),
        new Lesson("Breezily", "Advanced", new String[]{"Practice over a safe floor; do not start above a valuable world.", "Face backward and find a down angle that keeps the next side face visible.", "Strafe left and right while moving backward to manage edge exposure.", "Place when a valid side face is under the crosshair; use a rhythm you can repeat.", "Goal: short 3-block bursts; no universal CPS or angle guarantees success."}),
        new Lesson("Witchly", "Advanced", new String[]{"Learn diagonal sneak and short speed-bridge bursts first.", "Set up a diagonal route, facing back toward the starting corner.", "Use backward/strafe movement to alternate the reachable side faces.", "Place only when the face is visible; return to sneak if your line drifts.", "Goal: compare consistency with diagonal sneak, not a claimed fixed CPS."}),
        new Lesson("Godbridge", "Expert", new String[]{"Use creative practice with a safe floor and a full block stack.", "Align along a straight or diagonal route; experiment with a steep downward view.", "Time placement at each exposed side face while moving backward.", "Use short runs and deliberate jump resets; timing varies by game version.", "Goal: 2-4 blocks consistently before longer runs. No guaranteed 0-CPS method."}),
        new Lesson("Moonwalk", "Expert", new String[]{"Start with a short clear route and a safe landing below.", "Face the platform and establish a repeatable backward placement rhythm.", "Add brief strafe corrections instead of holding one long diagonal movement.", "Practice jump/reset timing in short segments; stop when the crosshair loses the face.", "Goal: record which movement timing works on this version, then repeat it."}),
        new Lesson("Telly", "Expert", new String[]{"Create a safe creative practice area; modern vanilla is not 1.8 combat.", "Sprint and jump from a stable platform while facing your travel direction.", "Turn back in the air and look toward a reachable placement face.", "Place the short segment, then turn forward and land before the next jump.", "Goal: one controlled jump/turn/placement cycle. This trainer does not auto-telly."}),
        new Lesson("Jump / staircase", "Intermediate", new String[]{"Choose a route with enough overhead space.", "Start with a solid block underfoot and a full block item selected.", "Jump and place the next step against an existing reachable face.", "Land securely before repeating; do not assume a destination in air is placeable.", "Goal: a 4-step staircase; inspect the support faces after each step."}),
        new Lesson("Hold-use / '0 CPS'", "Version dependent", new String[]{"0 CPS usually means no repeated physical presses, not no item-use input.", "Hold use in a safe sneak bridge to observe vanilla repeat delay.", "Adjust movement to the placement cadence; extra clicks cannot bypass server rules.", "Compare held-use with manual single clicks on the same short route.", "Goal: learn the difference between physical CPS, use attempts and blocks placed."})
    };
    private BridgeLessons() {}
    public static int lesson(int value) { return Math.max(0, Math.min(ALL.length - 1, value)); }
    public static int step(int value) { return Math.max(0, Math.min(4, value)); }
}
